create or replace function public.notify_staff_booking_request(p_appointment_id uuid) returns integer language plpgsql security definer set search_path = public as $$ declare v_count integer := 0; begin if auth.uid() is null or not exists (select 1 from public.appointments where id = p_appointment_id and patient_id = auth.uid()) then raise exception 'not_authorized'; end if; insert into public.notifications(user_id,kind,title,body,href,dedupe_key) select p.id,'booking_request','New appointment request','A patient submitted an appointment request for admin review.', '/admin#admin-appointments', 'appointment:' || p_appointment_id::text || ':staff-request' from public.profiles p where p.role in ('staff','admin') on conflict (dedupe_key) do nothing; get diagnostics v_count = row_count; return v_count; end; $$;
revoke all on function public.notify_staff_booking_request(uuid) from public;
grant execute on function public.notify_staff_booking_request(uuid) to authenticated;
create or replace function public.notify_patient_appointment(p_appointment_id uuid,p_kind text,p_title text,p_body text,p_href text,p_dedupe_key text) returns uuid language plpgsql security definer set search_path = public as $$ declare v_patient uuid; v_id uuid; begin if auth.uid() is null or not is_staff() then raise exception 'not_authorized'; end if; select patient_id into v_patient from public.appointments where id = p_appointment_id limit 1; if v_patient is null then raise exception 'appointment_not_found'; end if; insert into public.notifications(user_id,kind,title,body,href,dedupe_key) values(v_patient,p_kind,p_title,p_body,p_href,p_dedupe_key) on conflict (dedupe_key) do update set title=excluded.title, body=excluded.body, href=excluded.href returning id into v_id; return v_id; end; $$;
revoke all on function public.notify_patient_appointment(uuid,text,text,text,text,text) from public;
grant execute on function public.notify_patient_appointment(uuid,text,text,text,text,text) to authenticated;
